    { id:"p3h-182", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket väder bidrog till att Gustav II Adolf kom bort från sina trupper vid Lützen?", answer: "Dimma", accept: ["dimma","dimman"], explanation: "Han red in i fiendens led i dimman.", sources: ["sv:Slaget vid Lützen"] }
